// "debug: why the animation in StartupWindow stops working after 2 swipes?" (chat 2026-10-13)
//
// The split animation lives here instead of in XAML style triggers: storyboards started from
// different style triggers sit in separate animation layers, and the trigger declared later
// always wins while it holds its end value, so the animation got stuck after two swipes.
// BeginAnimation on the element replaces the previous animation and starts from the current value.

using System.Windows;
using System.Windows.Input;
using System.Windows.Media.Animation;

namespace NightfallEditor;

public partial class StartupWindow : Window
{
    private enum Pane { Create, Open }

    // Window content is 800 wide: rest 400 | 400, active side 520 | 280.
    private const double CreateWidthWide   = 520;
    private const double CreateWidthNarrow = 280;
    private const double InactiveOpacity   = 0.55;

    private static readonly Duration WidthDuration   = TimeSpan.FromMilliseconds(350);
    private static readonly Duration OpacityDuration = TimeSpan.FromMilliseconds(250);
    private static readonly IEasingFunction Ease     = CreateEase();

    private Pane? _activePane;

    public StartupWindow()
    {
        InitializeComponent();
    }

    private static IEasingFunction CreateEase()
    {
        var ease = new CubicEase { EasingMode = EasingMode.EaseOut };
        ease.Freeze();
        return ease;
    }

    private void ActivatePane(Pane pane)
    {
        if (_activePane == pane)
            return;                 // already there, don't restart the animation
        _activePane = pane;

        bool create = pane == Pane.Create;

        var width = new DoubleAnimation(create ? CreateWidthWide : CreateWidthNarrow, WidthDuration)
        {
            EasingFunction = Ease
        };
        CreatePane.BeginAnimation(WidthProperty, width);

        CreatePane.BeginAnimation(OpacityProperty, new DoubleAnimation(create ? 1.0 : InactiveOpacity, OpacityDuration));
        OpenPane.BeginAnimation(OpacityProperty,   new DoubleAnimation(create ? InactiveOpacity : 1.0, OpacityDuration));
    }

    private void CreatePane_MouseEnter(object sender, MouseEventArgs e)
    {
        ActivatePane(Pane.Create);
    }

    private void OpenPane_MouseEnter(object sender, MouseEventArgs e)
    {
        // Focus lock: don't shrink the form while the user is typing in it.
        if (CreateInputs.IsKeyboardFocusWithin)
            return;

        ActivatePane(Pane.Open);
    }

    private void CreateInputs_IsKeyboardFocusWithinChanged(object sender, DependencyPropertyChangedEventArgs e)
    {
        if ((bool)e.NewValue)
            ActivatePane(Pane.Create);
        else if (OpenPane.IsMouseOver)
            ActivatePane(Pane.Open);    // focus left the form while the mouse is already on the right
    }
}
